  "items": [
    {
      "id": "R1",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "서로 다른 현상인 괴사와 세포자멸사를 죽음의 외부적·능동적 발생 방식이라는 기준에서 대비한다."
    },
    {
      "id": "R2",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "올챙이 꼬리의 소멸은 불필요한 세포를 제거하는 세포자멸사의 구체적인 사례이다."
    },
    {
      "id": "R3",
      "type": "CAUSE",
      "otherName": "",
      "reason": "유해한 비정상적 세포의 제거가 질병으로부터 신체를 보호하는 실제 효과로 이어진다."
    },
    {
      "id": "R4",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "손상된 세포를 제거한다는 설명을 Bcl-2 감소와 카스파제 활성화 등의 세부 기전으로 풀어 준다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "유해한 세포를 제거하여 신체를 보호하는 기능을 바이러스 감염 세포의 제거 사례로 구체화한다."
    },
    {
      "id": "R6",
      "type": "OTHER",
      "otherName": "기능과 농도 변화의 연결",
      "reason": "Bcl-2의 억제 기능과 손상 시 농도 변화를 연결하지만 그 기능만으로 농도 감소가 설명되거나 두 진술 사이에 직접적인 인과가 성립하지는 않는다."
    },
    {
      "id": "R7",
      "type": "CAUSE",
      "otherName": "",
      "reason": "세포 손상으로 감소한 Bcl-2가 미토콘드리아 막의 파괴로 이어지는 실제 작용을 설명한다."
    },
    {
      "id": "R8",
      "type": "CAUSE",
      "otherName": "",
      "reason": "미토콘드리아 막의 파괴가 내부 물질의 방출을 일으킨다."
    },
    {
      "id": "R9",
      "type": "CAUSE",
      "otherName": "",
      "reason": "미토콘드리아에서 방출된 물질이 카스파제를 활성화하는 실제 작용을 한다."
    },
    {
      "id": "R10",
      "type": "CAUSE",
      "otherName": "",
      "reason": "카스파제-9에 의한 절단이 실행 카스파제의 활성화를 일으킨다."
    },
    {
      "id": "R11",
      "type": "CAUSE",
      "otherName": "",
      "reason": "활성화된 실행 카스파제의 작용이 세포 DNA의 절단을 일으킨다."
    },
    {
      "id": "R12",
      "type": "CAUSE",
      "otherName": "",
      "reason": "실행 카스파제에 의한 DNA 절단이 DNA 붕괴로 이어진다."
    },
    {
      "id": "R13",
      "type": "PROCESS",
      "otherName": "",
      "reason": "감염 세포 표면에 바이러스 단백질이 나타난 다음 이를 세포독성 T세포가 인식하는 단계로 이어진다."
    },
    {
      "id": "R14",
      "type": "PROCESS",
      "otherName": "",
      "reason": "바이러스 단백질을 비정상으로 인식한 뒤 감염 세포에 결합하는 단계의 순서를 제시한다."
    },
    {
      "id": "R15",
      "type": "PROCESS",
      "otherName": "",
      "reason": "세포독성 T세포가 감염 세포에 결합한 다음 단백질을 분비하는 단계로 진행된다."
    },
    {
      "id": "R16",
      "type": "CAUSE",
      "otherName": "",
      "reason": "분비된 단백질이 실제로 감염 세포막에 구멍을 형성한다."
    },
    {
      "id": "R17",
      "type": "PROCESS",
      "otherName": "",
      "reason": "앞 단계에서 만들어진 세포막의 구멍을 이용하여 다음 단계인 과립효소 B의 유입이 진행된다."
    },
    {
      "id": "R18",
      "type": "CAUSE",
      "otherName": "",
      "reason": "세포 안으로 유입된 과립효소 B가 실행 카스파제를 활성화한다."
    },
    {
      "id": "R19",
      "type": "CAUSE",
      "otherName": "",
      "reason": "과립효소 B에 의해 활성화된 실행 카스파제의 작용이 DNA 붕괴를 일으킨다."
    },
    {
      "id": "R20",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "세포자멸사가 시작되는 계기와 실행 카스파제가 활성화되는 경로가 서로 다른 두 경우를 대비한다."
    },
    {
      "id": "R21",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "동일한 실행 카스파제의 활성화가 한 경로에서는 카스파제-9에 의해, 다른 경로에서는 과립효소 B에 의해 이루어진다는 차이를 보여 준다."
    },
    {
      "id": "R22",
      "type": "OTHER",
      "otherName": "공통 결과",
      "reason": "서로 다른 두 경로가 실행 카스파제에 의한 DNA 붕괴라는 동일한 결과에 이른다는 공통점이며 인물이나 이론 사이의 견해 일치는 아니다."
    },
    {
      "id": "R23",
      "type": "CAUSE",
      "otherName": "",
      "reason": "실행 카스파제에 의한 DNA 붕괴가 DNA의 사다리 모양이라는 특징을 발생시킨다."
    },
    {
      "id": "R24",
      "type": "CAUSE",
      "otherName": "",
      "reason": "감염 세포에서 실행 카스파제가 일으킨 DNA 붕괴가 사다리 모양의 출현으로 이어진다."
    },
    {
      "id": "R25",
      "type": "PROCESS",
      "otherName": "",
      "reason": "세포가 먼저 쪼그라든 뒤 여러 조각으로 나뉘는 형태 변화의 순서를 제시한다."
    },
    {
      "id": "R26",
      "type": "PROCESS",
      "otherName": "",
      "reason": "핵의 분절에 이어 세포의 파편화가 나타나는 순서를 제시하며 직접적인 인과를 주장하지 않는다."
    },
    {
      "id": "R27",
      "type": "PROCESS",
      "otherName": "",
      "reason": "세포의 파편화 이후 세포막의 두 층이 뒤섞이는 다음 단계가 진행된다."
    },
    {
      "id": "R28",
      "type": "CAUSE",
      "otherName": "",
      "reason": "세포막의 두 층이 뒤섞이는 변화가 포스파티딜세린의 외부 노출로 이어진다."
    },
    {
      "id": "R29",
      "type": "CAUSE",
      "otherName": "",
      "reason": "바깥쪽으로 노출된 포스파티딜세린이 식세포의 자멸사 세포 인식을 일으키는 신호로 작용한다."
    },
    {
      "id": "R30",
      "type": "PROCESS",
      "otherName": "",
      "reason": "식세포가 자멸사한 세포를 인식한 다음 이를 포식하는 처리 순서를 제시한다."
    },
    {
      "id": "R31",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "식세포의 포식이 염증 유발 물질이 새어 나오기 전에 신속히 이루어진다는 세부 사항을 덧붙인다."
    },
    {
      "id": "R32",
      "type": "CAUSE",
      "otherName": "",
      "reason": "염증 유발 물질이 유출되기 전의 신속한 처리가 염증 반응의 발생을 막는 실제 작용을 설명한다."
    },
    {
      "id": "R33",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "세포자멸사와 괴사를 구별하는 논의가 죽음의 발생 방식에서 염증 반응의 유무라는 새로운 비교 기준으로 확장된다."
    },
    {
      "id": "R34",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "앞서 제시한 비정상적 세포의 제거 기능을 결말에서 제때 제거되게 한다는 표현으로 다시 진술한다."
    },
    {
      "id": "R35",
      "type": "CAUSE",
      "otherName": "",
      "reason": "비정상적 세포의 제거가 새로운 세포의 생성으로 이어지는 실제 작용을 설명한다."
    },
    {
      "id": "R36",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "비정상적 세포를 제거하는 세포자멸사의 기능을 악성 종양 등 질병의 치료 연구라는 새로운 영역에 활용한다."
    }
  ]
}

